#!/usr/bin/env python3
from pathlib import Path
import json,gzip,copy
from shapely.geometry import shape,box
P=Path(__file__).resolve().parent;C=P.parent/'contexts'
with gzip.open(P/'source-objects.geojson.gz','rt',encoding='utf-8') as h:objects={f['id']:f for f in json.load(h)['features']}
r=json.load(open(P/'recipes.json'));tasks=json.load(open(P/'assignment.json'))['municipalities'];city={c['municipality']:c for c in tasks}
def get(c,kind,pred,scope=None):
 k=city[c]['contextKey'];fs=json.load(gzip.open(C/k/(kind+'.geojson.gz'),'rt'));out=[]
 for f in fs['features']:
  if not pred(f):continue
  if scope and not shape(f['geometry']).intersects(box(*scope)):continue
  f=copy.deepcopy(f);f['properties']['originalId']=f['id'];f['id']=k+':'+kind+':'+f['id'];objects[f['id']]=f;out.append(f['id'])
 return out
def roads(c,ns,b=None):return get(c,'roads',lambda f:f['properties']['name'] in ns,b)
def add(c,n,ns,url,note,ev,b=None,allow=40,partial=False):
 if any(x['municipality']==c and x['name']==n for x in r):return
 ids=roads(c,ns,b)
 if not ids:raise ValueError((c,n,'No roads'))
 k=city[c]['contextKey'];mun=json.load(open(C/k/'municipality.geojson'))['features'][0]['geometry']
 r.append(dict(batch='batch-02',municipality=c,name=n,operation='street-envelope',inputIds=ids,inputScopes={i:b for i in ids} if b else {},clipGeometry=mun,sourceUrl=url,supportingUrls=list(dict.fromkeys(objects[i]['properties']['source']['url'] for i in ids)),evidenceFiles=['evidence/'+ev],partialFootprint=partial,frontageAllowanceM=allow,approximationNote=note+' This is a low-confidence convex envelope of the actual named street network with an inferred '+str(allow)+' m external plot/verge allowance, clipped to the native municipality. Outer joins, frontage depth and historical extremities are inferred; no published exact boundary or point-only construction is claimed.'+(' The recorded coordinate scope selects only the local portion of longer roads, not an independent box-shaped boundary.' if b else '')))
add('Kőszeg','Lakótelep',['Űrhajósok utcája','Rohonci utca','Írottkő utca'],'https://koszeg.hu/pictures/downloadmanager/33/1241/koszeg-tak_elfogadott_1640.pdf','The municipal character guide locates the estate behind/west of Rákóczi street, and municipal notices identify the Rohonci estate portion. Original Űrhajósok, Írottkő and Rohonci streets span the whole estate grid.','housing-estates-search.json',allow=45)
add('Csorna','Felsőszeri lakótelep',['Felsőszeri lakótelep'],'https://njt.jog.gov.hu/jogszabaly/2003-13-SP-5Y3336','Municipal records name the estate and its Laky Döme approach. Both complete original estate-named access streets span its occupied blocks, rather than just its sports/parking surfaces.','housing-estates-search.json',allow=45)
add('Csorna','Petőfi lakótelep',['Petőfi lakótelep','Thököly út','Andrássy utca'],'https://njt.jog.gov.hu/jogszabaly/2003-13-SP-5Y3336','Municipal records explicitly identify the Petőfi estate/Andrássy corner. The estate road and local Thököly/Andrássy perimeter portions estimate the complete housing blocks.','housing-estates-search.json',[17.2538,47.6148,17.2570,47.6187],45)
add('Celldömölk','Kodály Zoltán lakótelep',['Akácfa utca','Balassi Bálint utca','Hársfa utca','Kodály Zoltán utca','Tátra utca','Tompa Mihály utca','Vörösmarty utca'],'https://helyimenetrend.mavcsoport.hu/files/public/helyi_menetrendek/celldomolk/celldomolk_hkhi.pdf','The official transit map text names this estate. The archived OSM-derived quarter street list associates the complete local Kodály/Hársfa/Akácfa/Balassi/Tátra/Tompa/Vörösmarty grid with it; the source roads estimate a whole residential quarter.','estate-hill-street-lists.json')
add('Celldömölk','Mikes-lakótelep',['Arad utca','Belovári István utca','Csokonai utca','Gábor Áron utca','Gyár utca','Mikes Kelemen utca','Szalóky Sándor utca','Tulipán utca'],'https://helyimenetrend.mavcsoport.hu/files/public/helyi_menetrendek/celldomolk/celldomolk_hkhi.pdf','The official transit map text names this estate. The archived OSM-derived quarter inventory lists these actual Mikes/Belovári/Szalóky/Tulipán and surrounding streets, supporting a whole-estate occupied extent.','estate-hill-street-lists.json')
add('Cserszegtomaj','I. körzet',['Diófa utca','Gyöngyvirág utca','Hársfa utca','Kovács utca','Meggyfa utca','Panoráma köz','Péter-Pál utca','Tulipán utca'],'https://utcak-magyarorszag.openalfa.com/i-korzet','The actually opened OSM-derived I. körzet street inventory associates these eight streets with the named quarter. All available original named street segments support a coarse occupied district extent. This is not a claimed legal electoral/service district.','gyor-cserszeg-street-lists.json')
add('Cserszegtomaj','II. körzet',['Barlang utca','Majori utca','Ménes utca','Palotai köz'],'https://utcak-magyarorszag.openalfa.com/ii-korzet','The actually opened OSM-derived II. körzet street inventory associates Barlang, Majori, Ménes and Palotai with this separately named quarter. Original street geometry estimates its occupied grid; exact open/rural margins are not established.','gyor-cserszeg-street-lists.json',allow=45)
add('Őriszentpéter','Baksaszer',['Baksaszer'],'https://archeodatabase.hnm.hu/hu/node/88512','The primary archaeological inventory and official transit-derived sources separately name Baksaszer. The complete original roads actually named Baksaszer span this sparse traditional settlement cluster, giving a whole occupied-szer estimate rather than just an institutional parcel.','west-localities-search.json',allow=55)
add('Marcali','Papagáj Lakótelep',['Dózsa György utca','Múzeum köz','Széchenyi utca'],'https://gamesz.marcali.hu/palyazat/','The municipal operator describes the Dózsa-street Papagáj estate as four four-storey housing blocks with 240 homes. The local Dózsa/Széchenyi/Múzeum street portions enclose those whole estate blocks and internal green space. The primary text describes the estate, not this precise outer envelope.','west-localities-search.json',[17.4091,46.5770,17.4131,46.57945],20)
add('Marcali','Tiszti Lakótelep',['Móra Ferenc utca','Gábor Áron utca'],'https://new.marcali.hu/azt-beszelik-a-varosban-dr-suto-laszlo-polgarmestert-kerdeztuk/','The municipal mayor interview explicitly identifies the Móra Ferenc street works with the former officers estate. Its actual Móra/Gábor access grid defines the whole small apartment-block estate estimate; the adjacent hospital is not substituted as the estate footprint.','remaining-west-localities.json',allow=45)
add('Abda','Radnóti Miklós lakótelep',['Radnóti Miklós lakótelep','Duna utca','Zöldmező utca'],'https://utcak-magyarorszag.openalfa.com/radnoti-miklos-lakotelep','The archived named-quarter street inventory identifies the estate street, Duna and Zöldmező streets. Original street geometry estimates the occupied housing grid instead of treating the whole Abda residential parent as the estate.','estate-hill-street-lists.json',allow=40)
add('Keszthely','Szendreytelep',['Szendrey major','Szendreytelepi út','Fenyves allé'],'https://keszthely.hu/latnivalok/muzeumok/szendrey-julia-emlekhaz-keszthely/?map=on','The municipal museum page identifies the former Újmajor as today Szendrey-telep, on the university-managed estate. The complete estate-named access grid and its local Fenyves allé edge estimate the farm/residential compound, not just the birth-house building. Far-reaching approach-road portions are excluded.','balaton-rural-search.json',[17.2253,46.7475,17.2309,46.7500],35)
add('Nemesvita','Cseresnyés',['Cseresznyés utca','Cseresznyés köz','Nemeshegy utca'],'https://utcak-magyarorszag.openalfa.com/utcak/cseresznyes-koez-cseresnyes-nemesvita','The archived named-quarter street associations identify Cseresznyés street/close and Nemeshegy street as this hillside quarter. Their actual geometry estimates the occupied vineyard/residential strip; no huge Keszthelyi-hegység parent surface is substituted.','balaton-rural-search.json',allow=45)
add('Szigliget','Belsőhegy',['Belsőhegyi utca','Kamonkői út'],'https://njt.jog.gov.hu/jogszabaly/2010-5-SP-5Y3852','The municipal building regulation separately names the Belső-hegy landscape and neighboring hills. The actual Belsőhegyi access street and local Kamonkői hillside grid estimate this whole occupied hill-side quarter, not the whole Szigliget residential parent.','middle-west-search.json',[17.4370,46.7860,17.4475,46.7960],45)
add('Szigliget','Külsőhegy',['Külsőhegyi út','Rókarántói út'],'https://njt.jog.gov.hu/jogszabaly/2010-5-SP-5Y3852','The municipal building regulation separately names Külső-hegy. Original Külsőhegyi/Rókarántói hillside roads estimate the occupied quarter landscape. The limits between named hills and unbuilt vineyard/woodland margins remain uncertain.','middle-west-search.json',allow=50)
add('Mencshely','Halomhegy',['Halomhegyi út','Szivárvány utca','Puttony köz','Pincesor utca','Vulkán utca'],'https://docplayer.hu/1448835-Mencshely-telepulesszerkezeti-terv.html','The retrieved planning-text mirror describes the Halomhegy former enclosed-garden/vineyard district. Its real Halomhegyi/Pincesor/Puttony/Vulkán/Szivárvány street network estimates the whole occupied vineyard/cellar hill-side extent, rather than the lookout building. Unbuilt agricultural extremities remain uncertain.','eastern-shard-search.json',allow=55)
add('Szigetvár','Móra Ferenc-lakótelep',['Móra Ferenc lakótelep'],'https://www.szigetvar.hu/hu/palyazat/komplex-fejlesztes-szigetvari-mora-ferenc-lakotelepen','The municipality explicitly names the estate and its numbered apartment blocks. All original source roads named Móra Ferenc lakótelep span the estate, including its internal court/access area; the estimate is not just the refurbished number-1 building.','eastern-shard-search.json',allow=45)
add('Bárdudvarnok','Olajhegy',['Olajhegy lakótelep'],'https://njt.jog.gov.hu/jogszabaly/2023-16-SP-5Y2468.0','The municipality separately names Olajhegy among its outlying localities. Actual roads named Olajhegy lakótelep span the detached settlement. The inferred envelope covers its occupied hill-side street network, rather than the larger Zselic parent landscape.','south-localities-search.json',allow=55)
krisna=['Gauranga tér','Bhaktivedanta sétány','Varsana utca','Nitáj körút','Rádha-Krisna körút']
add('Somogyvámos','Krisna-völgy',krisna,'https://www.krisnavolgy.hu/rolunk','The community operator identifies its Somogyvámos centre and farm. The actual separately named internal community streets and paths estimate the occupied village/garden core, including spaces between buildings. The entire 260–300 ha agricultural property is not established by these inputs, so this is explicitly a partial community footprint.','south-localities-search.json',allow=50,partial=True)
add('Sárvár','Lánkapuszta',['Lánkapuszta','Balogh Ádám utca','Vak Bottyán utca','Magasházi út','Posta utca','Víztorony köz'],'https://njt.jog.gov.hu/jogszabaly/2016-37-SP-5Y3245.8','Municipal planning and heritage records identify Lánkapuszta and its central water tower, with Posta/Víztorony addresses also recorded. The actual local village streets span its detached occupied settlement, including the label between its eastern and western street clusters. Wider historical fields are unresolved.','rural-west-search.json',allow=45)
(P/'recipes.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
(P/'source-objects.geojson.gz').write_bytes(gzip.compress(json.dumps(dict(type='FeatureCollection',features=list(objects.values())),ensure_ascii=False,separators=(',',':')).encode(),mtime=0))
print(len(r),'recipes',len(objects),'objects')
